113: QString SysApiLoader::platformSystemLibraryDirectory()
114: {
115:     static const auto result = []() -> QString {
116: #ifdef Q_OS_WINDOWS
117:         QVarLengthArray<wchar_t, MAX_PATH> buf = {};
118:         const UINT len = ::GetSystemDirectoryW(buf.data(), MAX_PATH);
119:         if (len > MAX_PATH) {
120:             // No need to +1 here, GetSystemDirectoryW() will always give us a null terminator.
121:             buf.resize(len);
122:             ::GetSystemDirectoryW(buf.data(), len);
123:         }
124:         return QString::fromWCharArray(buf.constData(), len);
125: #else
126:         return FRAMELESSHELPER_STRING_LITERAL("/usr/lib");
127: #endif
128:     }();
129:     return result;
