132: QString SysApiLoader::generateUniqueKey(const QString &library, const QString &function)
133: {
134:     Q_ASSERT(!library.isEmpty());
135:     Q_ASSERT(!function.isEmpty());
136:     if (library.isEmpty() || function.isEmpty()) {
137:         return {};
138:     }
139:     QString key = QDir::toNativeSeparators(library);
140:     // Remove path, only keep the file name.
141:     if (const qsizetype lastSeparatorPos = key.lastIndexOf(QDir::separator()); lastSeparatorPos >= 0) {
142:         key.remove(0, lastSeparatorPos);
143:     }
144: #ifdef Q_OS_WINDOWS
145:     key = key.toLower();
146: #endif // Q_OS_WINDOWS
147:     static const QString suffix = platformSharedLibrarySuffixName();
148:     if (!key.endsWith(suffix)) {
149:         key.append(suffix);
150:     }
151:     key.append(u'@');
152:     key.append(function);
153:     return key;
154: }
