181: bool SysApiLoader::isAvailable(const QString &library, const QString &function)
182: {
183:     Q_ASSERT(!library.isEmpty());
184:     Q_ASSERT(!function.isEmpty());
185:     if (library.isEmpty() || function.isEmpty()) {
186:         return false;
187:     }
188:     const QString key = generateUniqueKey(library, function);
189:     const auto it = g_sysApiLoaderData()->constFind(key);
190:     if (it != g_sysApiLoaderData()->constEnd()) {
191: #if FRAMELESSHELPER_CONFIG(debug_output)
192:         if (isDebug()) {
193:             DEBUG << Q_FUNC_INFO << "Function cache found:" << key;
194:         }
195: #endif
196:         return (it.value() != nullptr);
197:     } else {
198:         const QFunctionPointer symbol = SysApiLoader::resolve(library, function);
199:         g_sysApiLoaderData()->insert(key, symbol);
200: #if FRAMELESSHELPER_CONFIG(debug_output)
201:         if (isDebug()) {
202:             DEBUG << Q_FUNC_INFO << "New function cache:" << key << (symbol ? "[VALID]" : "[NULL]");
203:         }
204: #endif
205:         if (symbol) {
206:             DEBUG << "Successfully loaded" << function << "from" << library;
207:             return true;
208:         } else {
209:             WARNING << "Failed to load" << function << "from" << library;
210:             return false;
211:         }
212:     }
213: }
